/// <summary>
/// The <c>METCustInterestPost_Extension</c> class extends the logic of interest note posting
/// </summary>
[ExtensionOf(classStr(CustInterestPost))]
public final class METCustInterestPost_Extension
{
    private DialogField dialogUseRunDateAsPostingDate;
    private NoYes useRunDateAsPostingDate;

    #DEFINE.CurrentVersion(1)
    #LOCALMACRO.CurrentList
        useRunDateAsPostingDate
    #ENDMACRO

}

Method.Source:
/// <summary>
/// Gets a class that contains the methods that are described by the <c>RunBaseDialogable</c> interface.
/// </summary>
/// <returns>
/// A class that contains the methods that are described by the <c>RunBaseDialogable</c> interface.
/// </returns>
/// <remarks>
/// A dialog box can be either built by using the <c>Dialog</c> class or by using a class that is
/// created in the Application Object Tree (AOT).
/// </remarks>
public Object dialog()
{
    DialogRunbase dialogRunbase = next dialog();

    useRunDateAsPostingDate = NoYes::No;
    dialogUseRunDateAsPostingDate = dialogRunbase.addFieldValue(extendedTypeStr(NoYesId), useRunDateAsPostingDate, "@MET:CustInterestPostUseRunDateAsPostingDate");

    return dialogRunbase;
}

/// <summary>
/// dialog Post Run
/// </summary>
/// <param name = "dialog">dialog</param>
public void dialogPostRun(DialogRunbase dialog)
{
    next dialogPostRun(dialog);

    dialogUseRunDateAsPostingDate.registerOverrideMethod(methodStr(FormCheckBoxControl, modified), methodStr(CustInterestPost, resetPostingDate), this);
}

private boolean resetPostingDate(FormCheckBoxControl _control)
{
    boolean ret = true;

    dialogPostingDate.allowEdit(_control.value() ? false : true);
    dialogPostingDate.value(_control.value() ? dateNull() : DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));

    return ret;
}

/// <summary>
/// get values from dialog
/// </summary>
/// <returns>
/// true/false
/// </returns>
public boolean getFromDialog()
{
    boolean ret = next getFromDialog();

    postingDate = dialogPostingDate.value() != dateNull() ? dialogPostingDate.value() : DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    useRunDateAsPostingDate = dialogUseRunDateAsPostingDate.value();

    return ret;
}

/// <summary>
/// pack
/// </summary>
public container pack()
{
    container packedClass = next pack();
    return SysPackExtensions::appendExtension(packedClass, classStr(METCustInterestPost_Extension), this.metPack());
}

/// <summary>
/// unpack
/// </summary>
/// <param name = "_packedClass">packedClass</param>
/// <returns>
/// true/false
/// </returns>
public boolean unpack(container _packedClass)
{
    boolean result = next unpack(_packedClass);

    if (result)
    {
        container metState = SysPackExtensions::findExtension(_packedClass, classStr(METCustInterestPost_Extension));
        if (!this.metUnpack(metState))
        {
            result = false;
        }
    }

    return result;
}

private boolean metUnpack(container packedClass)
{
    Integer version = RunBase::getVersion(packedClass);
    switch (version)
    {
        case #CurrentVersion:
            [version, #currentList] = packedClass;
            break;
        default:
            return false;
    }
    return true;
}

/// <summary>
/// parm UseRunDateAsPostingDate
/// </summary>
/// <param name = "_useRunDateAsPostingDate">useRunDateAsPostingDate</param>
/// <returns>
/// NoYes
/// </returns>
public NoYes parmUseRunDateAsPostingDate(NoYes _useRunDateAsPostingDate = useRunDateAsPostingDate)
{
    useRunDateAsPostingDate = _useRunDateAsPostingDate;
    return useRunDateAsPostingDate;
}

/// <summary>
/// Contains the code that performs the actual job of the class.
/// </summary>
public void run()
{
    if (useRunDateAsPostingDate)
    {
        postingDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    }

    next run();
}
